import requests
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi'
terms=['(ADRB1 OR beta-1 adrenergic receptor OR Arg389Gly OR rs1801253) AND flecainide','(Arg389Gly OR rs1801253 OR ADRB1) AND (antiarrhythmic OR arrhythmia) AND beta blocker']
for q in terms:
 r=requests.get(u,params={'db':'pubmed','term':q,'retmode':'json','retmax':20},timeout=20)
 d=r.json()['esearchresult']; print('\nQUERY',q,'COUNT',d['count'],'IDS',d['idlist'])
 if d['idlist']:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(d['idlist']),'retmode':'json'},timeout=20).json()['result']
  for i in d['idlist']: print(i,x[i].get('title',''),x[i].get('pubdate',''))
